// "0xLLHH" wire-byte-concat -> canonical little-endian u16 id
fn canon_id(s: &str) -> u16 {
    let h = s.trim_start_matches("0x").trim_start_matches("0X");
    let b0 = u8::from_str_radix(&h[0..2], 16).unwrap();
    let b1 = u8::from_str_radix(&h[2..4], 16).unwrap();
    (b0 as u16) | ((b1 as u16) << 8)
}

